INSERT INTO topics (id, name, visibility, maintainer, description, current_version)
VALUES ('global-us-news', 'Global and U.S. News', 'public', 'Patrick', 'The day''s significant news, worldwide and in the United States, as surfaced by the New York Times, the Economist and the Wall Street Journal, organized by the Economist''s sections, with the top two or three stories in each, summarized and linked.', 0)
