INSERT INTO topic_versions (topic_id, version, definition, note)
SELECT 'global-us-news',
       COALESCE((SELECT MAX(version) FROM topic_versions WHERE topic_id = 'global-us-news'), 0) + 1,
       '{"id":"global-us-news","name":"Global and U.S. News","visibility":"public","maintainer":"Patrick","description":"The day''s significant news, worldwide and in the United States, as surfaced by the New York Times, the Economist and the Wall Street Journal, organized by the Economist''s sections, with the top two or three stories in each, summarized and linked.","cadence":"twice daily, runs at 05:05 and 17:05 America/New_York (09:05 and 21:05 UTC in daylight time); the later run is the edition for the day and earlier runs fold beneath it","edition_size":"2 to 3 stories per category unless the category sets max_stories; a category with nothing significant is omitted","categories":[{"id":"leaders","name":"Leaders","weight":1},{"id":"briefing","name":"Briefing","weight":1},{"id":"united-states","name":"United States","weight":1},{"id":"international","name":"International","weight":1},{"id":"finance-and-economics","name":"Finance and economics","weight":1,"max_stories":4},{"id":"business","name":"Business","weight":1,"max_stories":4},{"id":"europe","name":"Europe","weight":1},{"id":"asia","name":"Asia","weight":1},{"id":"china","name":"China","weight":1},{"id":"middle-east-and-africa","name":"Middle East and Africa","weight":1},{"id":"the-americas","name":"The Americas","weight":1},{"id":"science-and-technology","name":"Science and technology","weight":1}],"category_notes":["Weights are all 1.0 at launch. They exist so that personal signals and a later private view can reweight them without changing the topic''s shape.","''The world this week'' is read as agenda only; it is a digest, not a category.","Every candidate, from any source, is assigned to exactly one category by the agent. NYT feeds map naturally: World to the regional categories, U.S. and Politics to United States, Business to Business or Finance and economics.","WSJ feeds map: World to the regional categories or International, US Business to Business, Markets to Finance and economics."],"entities":[],"deprioritize":["celebrity and entertainment news","sports, except an event of national or international consequence","individual crime stories without systemic significance","opinion and commentary, unless the edition is explicitly surfacing a leader","incremental product announcements","live-blog and ''what we know'' rolling formats"],"agenda_sources":[{"publisher":"New York Times","window_hours":48,"feeds":[{"name":"Home page","url":"https://rss.nytimes.com/services/xml/rss/nyt/HomePage.xml"},{"name":"World","url":"https://rss.nytimes.com/services/xml/rss/nyt/World.xml"},{"name":"U.S.","url":"https://rss.nytimes.com/services/xml/rss/nyt/US.xml"},{"name":"Politics","url":"https://rss.nytimes.com/services/xml/rss/nyt/Politics.xml"},{"name":"Business","url":"https://rss.nytimes.com/services/xml/rss/nyt/Business.xml"}],"role":"agenda"},{"publisher":"The Economist","window_hours":168,"feeds":[{"name":"The world this week","url":"https://www.economist.com/the-world-this-week/rss.xml","agenda_only_digest":true},{"name":"Leaders","url":"https://www.economist.com/leaders/rss.xml"},{"name":"Briefing","url":"https://www.economist.com/briefing/rss.xml"},{"name":"United States","url":"https://www.economist.com/united-states/rss.xml"},{"name":"International","url":"https://www.economist.com/international/rss.xml"},{"name":"Finance and economics","url":"https://www.economist.com/finance-and-economics/rss.xml"},{"name":"Business","url":"https://www.economist.com/business/rss.xml"},{"name":"Europe","url":"https://www.economist.com/europe/rss.xml"},{"name":"Asia","url":"https://www.economist.com/asia/rss.xml"},{"name":"China","url":"https://www.economist.com/china/rss.xml"},{"name":"Middle East and Africa","url":"https://www.economist.com/middle-east-and-africa/rss.xml"},{"name":"The Americas","url":"https://www.economist.com/the-americas/rss.xml"},{"name":"Science and technology","url":"https://www.economist.com/science-and-technology/rss.xml"}],"window_note":"The Economist publ